def analyze_frame(grid):
    """Find rectangular frame of 3s"""
    h, w = len(grid), len(grid[0])

    # Find top-left and bottom-right of frame
    top, left = None, None
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                if top is None:
                    top, left = r, c
                break
        else:
            continue
        break

    bottom, right = None, None
    for r in range(h - 1, -1, -1):
        for c in range(w):
            if grid[r][c] == 3:
                if bottom is None:
                    bottom, right = r, c
                break
        else:
            continue
        break

    # Check if it's a rectangular frame
    for r in range(top, bottom + 1):
        for c in range(left, right + 1):
            if grid[r][c] != 3:
