def transform(grid):
    """Transform: fill interior of 3-frame with concentric pattern"""
    h, w = len(grid), len(grid[0])

    # Find frame
    top, left, bottom, right = h, w, -1, -1
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                top = min(top, r)
                left = min(left, c)
                bottom = max(bottom, r)
                right = max(right, c)

    if top == h or right < left:
        return grid  # No frame found

    # Check for special cell in interior
    special_val = 0
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            if grid[r][c] != 0:
                special_val = grid[r][c]
                break
        if special_val != 0:
            break

    # Create output grid (copy input)
    result = [row[:] for row in grid]

    # Fill interior based on Manhattan distance from frame
    for r in range(top + 1, bottom):
        for c in range(left + 1, right):
            # Manhattan distance from frame (minimum to any of 4 sides)
            dist = min(
                r - (top + 1),
                (bottom - 1) - r,
                (left + 1) - c,
                (right - 1) - c
            )

            if grid[r][c] != 0:  # Special cell
